import pytest

from error_guard import validate

BAD_VALUES = [
  "Traceback (most recent call last): File \"/app/main.py\"",
  "SELECT * FROM users WHERE id = 1",
  "sqlite3.OperationalError: no such table",
  "/home/cat/app/config.py",
  "C:\\app\\config.py",
  "10.0.0.12:5432 refused",
  "token=abc123",
  "password=secret",
  "access_key=AKIA",
  "",
  "",
  "File \"/srv/app/db.py\", line 42",
  "postgresql://user:pass@db.internal/app",
  "redis://10.0.0.5:6379",
  "Traceback\n  at handler"
]


@pytest.mark.parametrize("value", BAD_VALUES)
def test_bad_value_is_rejected(value):
    with pytest.raises((ValueError, TypeError)):
        validate(value)
